// Security & Circular Sync Guardrail
const crypto = require('crypto');
const secret = $env.APOLLO_WEBHOOK_SECRET || 'secret_apollo_webhook_token';
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

// 1. Circular Sync Guardrail - abort if originated from n8n pipeline
const automationOrigin = body.contact?.attributes?.AUTOMATION_ORIGIN || body.attributes?.AUTOMATION_ORIGIN || body.automation_origin;
if (automationOrigin === 'n8n_brevo_pipeline') {
  return [{
    json: {
      isAuthorized: false,
      isCircular: true,
      reason: 'Circular sync detected: payload already originated from n8n_brevo_pipeline',
      data: body
    }
  }];
}

// 2. Signature verification (if signature header provided)
const signature = headers['x-apollo-signature'] || headers['x-hub-signature'];
let signatureValid = true;

if (signature && secret !== 'secret_apollo_webhook_token') {
  const expected = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');
  if (signature !== `sha256=${expected}` && signature !== expected) {
    signatureValid = false;
  }
}

// Extract raw contact data
const contactData = body.contact || body.person || body.data || body;
const email = (contactData.email || body.email || '').trim().toLowerCase();

return [{
  json: {
    isAuthorized: signatureValid,
    isCircular: false,
    email: email,
    first_name: contactData.first_name || contactData.firstName || '',
    last_name: contactData.last_name || contactData.lastName || '',
    company_name: contactData.organization_name || contactData.company || '',
    raw_data: contactData,
    received_at: new Date().toISOString()
  }
}];

// Corporate Domain Validation & Classification
const FREE_EMAIL_PROVIDERS = new Set([
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com',
  'aol.com', 'mail.com', 'zoho.com', 'protonmail.com', 'yandex.com',
  'gmx.com', 'live.com', 'msn.com', 'me.com', 'inbox.com'
]);

const item = $input.first().json;
const email = item.email || '';
const parts = email.split('@');
const domain = parts.length === 2 ? parts[1].toLowerCase() : '';

const isCorporate = domain.length > 0 && !FREE_EMAIL_PROVIDERS.has(domain) && domain.includes('.');

return [{
  json: {
    ...item,
    domain: domain,
    isCorporateDomain: isCorporate,
    domainType: isCorporate ? 'B2B_CORPORATE' : 'B2C_GENERIC'
  }
}];

// ICP Lead Scoring & Attribution Engine
const rawInput = $input.first().json;
const person = rawInput.person || {};
const org = person.organization || {};

const email = rawInput.email || person.email || '';
const firstName = person.first_name || rawInput.first_name || 'Valued';
const lastName = person.last_name || rawInput.last_name || 'Contact';
const title = (person.title || person.headline || '').toLowerCase();
const seniority = (person.seniority || '').toLowerCase();
const companyName = org.name || rawInput.company_name || person.organization_name || 'Company';
const employeeCount = Number(org.estimated_num_employees || person.organization_num_employees || 0);
const industry = org.industry || person.industry || 'Technology';
const linkedinUrl = person.linkedin_url || '';
const domain = org.primary_domain || rawInput.domain || '';
const annualRevenue = org.annual_revenue_printed || org.annual_revenue || 'N/A';

// Scoring Calculation
let score = 0;

// 1. Seniority & Title
if (seniority === 'c_suite' || title.includes('founder') || title.includes('ceo') || title.includes('cto') || title.includes('cro') || title.includes('coo')) {
  score += 40;
} else if (seniority === 'vp' || title.includes('vice president') || title.includes('head of')) {
  score += 30;
} else if (seniority === 'director' || title.includes('director')) {
  score += 20;
} else if (seniority === 'manager' || title.includes('manager') || title.includes('lead')) {
  score += 10;
}

// 2. Company Size
if (employeeCount >= 50 && employeeCount <= 1000) {
  score += 30;
} else if (employeeCount > 1000) {
  score += 25;
} else if (employeeCount >= 10 && employeeCount < 50) {
  score += 15;
} else {
  score += 5;
}

// 3. Industry Fit
const targetIndustries = ['software', 'saas', 'information technology', 'internet', 'marketing', 'financial services'];
if (targetIndustries.some(ind => industry.toLowerCase().includes(ind))) {
  score += 20;
} else {
  score += 10;
}

// 4. Data Completeness bonus
if (linkedinUrl) score += 10;

// Determine Tier & Target Brevo List
let leadTier = 'TIER_3_SMB';
let targetListId = Number($env.BREVO_STANDARD_LIST_ID || 103);

if (score >= 70) {
  leadTier = 'TIER_1_ENTERPRISE';
  targetListId = Number($env.BREVO_TIER_1_LIST_ID || 101);
} else if (score >= 45) {
  leadTier = 'TIER_2_MIDMARKET';
  targetListId = Number($env.BREVO_TIER_2_LIST_ID || 102);
}

return [{
  json: {
    email: email,
    attributes: {
      FIRSTNAME: firstName,
      LASTNAME: lastName,
      COMPANY: companyName,
      JOB_TITLE: person.title || 'Executive',
      SENIORITY: person.seniority || 'Professional',
      DOMAIN: domain,
      INDUSTRY: industry,
      EMPLOYEE_COUNT: employeeCount,
      ESTIMATED_REVENUE: String(annualRevenue),
      LINKEDIN_URL: linkedinUrl,
      ICP_SCORE: score,
      LEAD_TIER: leadTier,
      AUTOMATION_ORIGIN: 'n8n_brevo_pipeline',
      ENRICHED_AT: new Date().toISOString()
    },
    listIds: [targetListId],
    leadTier: leadTier,
    icpScore: score,
    isTier1: leadTier === 'TIER_1_ENTERPRISE',
    companyName: companyName,
    fullName: `${firstName} ${lastName}`.trim()
  }
}];

