// Fallback & Generic Ingestion Path for B2C/Generic Domains
const item = $('Company Domain Filter').item.json;
return [{
  json: {
    email: item.email,
    attributes: {
      FIRSTNAME: item.first_name || 'Subscriber',
      LASTNAME: item.last_name || '',
      DOMAIN_TYPE: 'B2C_GENERIC',
      AUTOMATION_ORIGIN: 'n8n_brevo_pipeline',
      SYNCED_AT: new Date().toISOString()
    },
    listIds: [Number($env.BREVO_STANDARD_LIST_ID || 103)],
    message: 'Generic email routed to standard newsletter list without Apollo credits consumption'
  }
}];

// Global DLQ & Failure Interceptor
const errorData = $input.first().json;
return [{
  json: {
    status: 'PIPELINE_ERROR',
    timestamp: new Date().toISOString(),
    error_message: errorData.message || errorData.error || 'Unknown Pipeline Execution Error',
    node_context: errorData,
    recovery_action: 'Logged to Dead-Letter Queue (DLQ) for automated replay'
  }
}];

